-- ============================================================================
-- FC1: Separation & Slug Catching joins the catalog, the FIRST Facilities
-- course and the first row the `facilities` module has ever had.
--
-- Catalog row (module 'facilities'; path_order 39, the first free slot above
-- Production's 38 and below Economics' 53; prereq_slug NULL, the carried-over
-- answer "no hard prerequisite inside a module") plus the three capstones and
-- their eighteen graded fields, generated by
-- /root/fc-wip-separation/gen_course.py from fields.json and the capstone
-- constants in fc1_fields_capstone.mjs. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/separation, because the 78
-- lessons, the teaching lab and its three explorer panels ship in the zip and
-- not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A separator is sized by asking which of
-- several competing requirements binds first, and the discipline is knowing
-- which requirement each dimension came from, which verdict the vessel has to
-- survive, and which number on the page is a calculation rather than a table
-- somebody copied.
--
-- THE ENGINES. engines/facilities/separatorSizing.js (the Separator & Slug
-- Catcher Designer: the DAK z factor inside its range, K with its published
-- derating, Souders-Brown settling, vertical and horizontal two-phase sizing,
-- three-phase sizing with an exact oil-water interface and two droplet
-- verdicts, and the L/D family with feasibility, reasons and a preferred row)
-- and engines/facilities/spacing.js (the Facility Layout Mapper's missing
-- half: the spacing table, haversine distances, computed flare and pool fire
-- setbacks, and the layout check with its completeness reading), as repaired
-- in FC1-0 (engines #188) and then in engines #195, which added the nearFloor
-- flag beside floored and gave both floor comparisons 1e-9 of slack.
--
-- NOTHING GRADED DEPENDS ON A HELD-FOR-LITERATURE QUANTITY. The K derating of
-- 0.01 per 100 psi and the 0.12 floor are the customary rule of thumb as this
-- module records it, unchecked against the source, so every tier states its
-- own VENDOR K and the engine is called with kOverride. For the same reason
-- the Expert layout is handed the site's own setbacks and is graded on
-- radiation shortfalls only, never on a spacing TABLE figure.
--
-- THE CAPSTONE GRADES WHAT THE COURSE TEACHES A READER TO GET RIGHT: which
-- requirement each dimension came from (the diameter from the gas, the height
-- from the liquid), the verdicts a sized vessel has to survive, the exact
-- interface against the retired chord rule, the smallest FEASIBLE vessel in
-- band rather than the smallest vessel, and two layout rankings that name
-- different pairs. All eighteen graded values were swept against every number
-- the digest and the goldens publish and against every number handed to a
-- learner in a prompt, at each field's own tolerance: 0 collisions, and 0
-- pairwise.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('separation', 'Separation & Slug Catching', 'facilities', 39, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'separation', 'beginner', 'associate',
  'EJULEBE-1, a vertical two-phase inlet separator on a field the lessons never use',
  'Size one vessel from its stream',
  'EJULEBE-1, the vertical two-phase inlet separator on a field the lessons never use: gas 31 MMscfd at 740 psig and 105 degF with a gas gravity of 0.71; oil 7350 bopd at 29 degrees API; water 2480 bpd at a specific gravity of 1.06; liquid retention 4 minutes; an allowance of 6.5 ft above the liquid; and a vendor K of 0.33 quoted for the mist extractor, which the engine takes as typed and never derates. The vessel the vendor offered is 6.4 ft in diameter. Report six values from the gas at conditions, the settling and the vertical vessel. Densities in lb/ft3, rates in ft3/s, velocities in ft/s and lengths in ft, to four decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ejulebe1_gas_density_lbft3', 'label','Gas density at separator conditions', 'unit','lb/ft3', 'expected',2.8881765597102644, 'tol',0.0001),
    jsonb_build_object('key','ejulebe1_gas_actual_ft3s', 'label','Gas rate at separator conditions, the rate the vessel actually sees', 'unit','ft3/s', 'expected',6.729272607529208, 'tol',0.0001),
    jsonb_build_object('key','ejulebe1_terminal_velocity_fts', 'label','Souders-Brown terminal settling velocity at the vendor K', 'unit','ft/s', 'expected',1.4391934722920448, 'tol',1e-05),
    jsonb_build_object('key','ejulebe1_gas_diameter_ft', 'label','The diameter the gas demands', 'unit','ft', 'expected',2.4399421536430808, 'tol',0.0001),
    jsonb_build_object('key','ejulebe1_height_ft', 'label','Vessel height at the vendor diameter, retention plus allowance', 'unit','ft', 'expected',11.265612430317097, 'tol',0.0001),
    jsonb_build_object('key','ejulebe1_velocity_margin', 'label','Velocity margin at the vendor diameter', 'unit','dimensionless', 'expected',6.880197223424059, 'tol',1e-05)
  )
),
(
  'separation', 'intermediate', 'professional',
  'EJULEBE-2, the slug catcher behind it, and the ODEAMA flow station''s two radiation duties',
  'The horizontal vessel, the slug and the setbacks',
  'EJULEBE-2, the horizontal production separator: gas 46 MMscfd at 415 psig and 118 degF with a gas gravity of 0.66; oil 15500 bopd at 31 degrees API; water 4300 bpd at a specific gravity of 1.03; liquid retention 6 minutes; a vendor K of 0.4; a diameter of 9 ft; and a liquid level at 0.45 of the diameter. The slug catcher behind it takes a 620 bbl slug with 19800 bpd still arriving over an 8 minute hold, filled to 0.65 of the vessel, at an L/D of 5; the same slug is also laid out as a harp of 7 fingers of 26 inch inside diameter filled to 0.75. The ODEAMA flow station states two radiation duties: a flare relieving 27 kg/s of a gas of 47500 kJ/kg, radiating a fraction 0.28 at a transmissivity of 0.95 against an allowable 6.31 kW/m2; and a slop tank pool fire 24 m across burning at 0.048 kg/m2 per second, 41500 kJ/kg, radiating 0.32 at a transmissivity of 1 against an allowable 4.73 kW/m2. Report six values from the sized vessel, the two slug catcher layouts and the two computed setbacks. Lengths in ft, velocities in ft/s and distances in m, to four decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ejulebe2_liquid_length_ft', 'label','The length the liquid retention demands', 'unit','ft', 'expected',16.682754876448943, 'tol',0.0001),
    jsonb_build_object('key','ejulebe2_gas_velocity_fts', 'label','Gas velocity in the gas space', 'unit','ft/s', 'expected',0.5341820338116766, 'tol',1e-05),
    jsonb_build_object('key','ejulebe_slug_vessel_diameter_ft', 'label','Slug catcher vessel diameter at the stated L/D', 'unit','ft', 'expected',11.709968225674618, 'tol',0.0001),
    jsonb_build_object('key','ejulebe_finger_length_ft', 'label','Length of each finger in the harp', 'unit','ft', 'expected',179.83566824158774, 'tol',0.001),
    jsonb_build_object('key','odeama_flare_setback_m', 'label','Flare setback, computed from its own duty', 'unit','m', 'expected',65.5918520153159, 'tol',0.001),
    jsonb_build_object('key','odeama_pool_setback_edge_m', 'label','Pool fire setback measured from the pool edge', 'unit','m', 'expected',57.6530817483345, 'tol',0.001)
  )
),
(
  'separation', 'advanced', 'expert',
  'EJULEBE-3, the EJULEBE-4 scrubber family, and the ADANGA manifold yard judged against its own setbacks',
  'The interface, the family and the judgement',
  'EJULEBE-3, the three-phase separator: gas 21 MMscfd at 290 psig and 124 degF with a gas gravity of 0.73; oil 9600 bopd at a specific gravity of 0.8762 and a viscosity of 6.5 cP; water 7200 bpd at a specific gravity of 1.07 and a viscosity of 0.75 cP; oil retention 7 minutes and water retention 9 minutes; a water droplet specification of 350 micron and an oil droplet specification of 150 micron; a vendor K of 0.37; a diameter of 11 ft; and a liquid level at 0.55 of the diameter. EJULEBE-4, the vertical scrubber downstream of the compressor: gas 70 MMscfd at 620 psig and 96 degF with a gas gravity of 0.69; oil 1900 bopd at 30 degrees API; water 350 bpd at a specific gravity of 1.05; retention 3 minutes; an allowance of 7 ft; a vendor K of 0.31; offered at 3, 3.5, 4, 4.5, 5 and 6 ft against an L/D band of 2 to 4. The ADANGA manifold yard, judged in the Facility Layout Mapper against the site''s own stated setbacks: the yard flare at 100 m to 6.31 kW/m2 and the slop tank pool fire at 47 m to 4.73 kW/m2, with a portable flare that was never placed and a second slop tank carrying no coordinates. Report six values from the three-phase split, the two droplet crossings, the preferred vessel of the family and the two layout rankings. Lengths in ft, times in s, distances in m and the fraction as a fraction, to four decimals or better.',
  jsonb_build_array(
    jsonb_build_object('key','ejulebe3_interface_height_ft', 'label','Oil-water interface at its exact height', 'unit','ft', 'expected',3.5272802173244173, 'tol',1e-05),
    jsonb_build_object('key','ejulebe3_water_drop_fall_s', 'label','Time for the specified water droplet to cross the oil layer', 'unit','s', 'expected',388.0364348552262, 'tol',0.001),
    jsonb_build_object('key','ejulebe3_oil_drop_rise_s', 'label','Time for the specified oil droplet to rise through the water layer', 'unit','s', 'expected',340.8355864500273, 'tol',0.001),
    jsonb_build_object('key','ejulebe4_preferred_height_ft', 'label','Height of the preferred vessel in the family', 'unit','ft', 'expected',9.094348494300087, 'tol',0.0001),
    jsonb_build_object('key','adanga_worst_absolute_shortfall_m', 'label','Worst absolute shortfall on the layout', 'unit','m', 'expected',53.82226310078884, 'tol',0.0001),
    jsonb_build_object('key','adanga_worst_relative_fraction', 'label','Worst relative shortfall on the layout, as a fraction of the requirement', 'unit','fraction', 'expected',0.6200257720948125, 'tol',1e-06)
  )
)
on conflict (app_slug, tier) do nothing;
